css:
/* ═══ Petal OS — a pastel pixel desktop for Marinara Engine, by Pix (round 4) ═══
   One idea: every surface is a crisp little window on a soft pixel city. Pixel art lives in the
   chrome (title bars, _ [] X buttons, bevels, cursor, icons); the text itself stays big and clean.
   Day = pink paper windows on a morning city. Night = plum CRT windows with glowing pink title bars.
   Fonts (bundled, OFL): Petal Display (Silkscreen), Petal Pixel (Pixelify Sans), Petal Term (VT323). */

:root,
:root[data-theme="light"],
:root[data-theme="dark"] {
  --mari-tokens-version: 1;
  --mari-window-title: on;

  /* ── palette: day ── */
  --p-ink: #4a2340;        /* text, borders */
  --p-ink-2: #7a4468;      /* secondary text (5.9:1 on paper) */
  --p-paper: #fff6fa;      /* window bodies */
  --p-paper-2: #fdeaf2;    /* sunken fields, rows */
  --p-shell: #f4c6d7;      /* title bars, top bar */
  --p-shell-2: #f9dce7;
  --p-rose: #e05a8a;       /* accent fills */
  --p-rose-text: #a82c5c;  /* accent as text (5.6:1 on paper) */
  --p-peri: #c3c9f1;       /* user windows' title bar */
  --p-mint: #bfe8d9;
  --p-hi: #ffffff;         /* bevel highlight */
  --p-lo: #e2a3be;         /* bevel shadow */
  --p-drop: rgba(74, 35, 64, 0.22);
  --p-desk: #fbe3ef;
  --p-title-ink: #4a2340;
  --p-btns: url("theme:winbtns-day.png");
  --p-heart: url("theme:heart.png");
  --p-dots: url("theme:dots-day.png");

  --p-t: 28px; /* title bar height */
  --p-term: "Petal Term", "VT323", ui-monospace, monospace;
  --p-pixel: "Petal Pixel", "Pixelify Sans", system-ui, sans-serif;
  --p-display: "Petal Display", "Silkscreen", ui-monospace, monospace;

  /* ── app tokens ── */
  --background: #fbe3ef;
  --foreground: var(--p-ink);
  --card: var(--p-paper);
  --card-foreground: var(--p-ink);
  --popover: var(--p-paper);
  --popover-foreground: var(--p-ink);
  --primary: #c23d70;
  --primary-foreground: #fff6fa;
  --secondary: var(--p-paper-2);
  --secondary-foreground: var(--p-ink);
  --muted: var(--p-paper-2);
  --muted-foreground: var(--p-ink-2);
  --accent: var(--p-shell-2);
  --accent-foreground: var(--p-ink);
  --destructive: #b3263e;
  --destructive-foreground: #fff6fa;
  --border: #d99ab6;
  --input: #d99ab6;
  --ring: var(--p-rose);
  --radius: 0px;
  --sidebar: #fbe3ef;
  --sidebar-foreground: var(--p-ink);
  --sidebar-border: var(--p-ink);
  --sidebar-accent: var(--p-shell-2);
  --sidebar-accent-foreground: var(--p-ink);

  --ov-line: #e3b3c8;
  --ov-text: var(--p-ink);
  --ov-muted: var(--p-ink-2);
  --ov-dim: #8d5a7b;
  --ov-accent: var(--p-rose-text);
  --ov-hover: rgba(224, 90, 138, 0.1);
  --ov-active-bg: rgba(224, 90, 138, 0.18);
  --ov-mode-conversation: #5b6bc4;
  --ov-mode-roleplay: #a82c5c;
  --ov-mode-game: #2f7f68;
  --mari-mode-conversation: #5b6bc4;
  --mari-mode-roleplay: #a82c5c;
  --mari-mode-game: #2f7f68;
  --mari-home-pink: #a82c5c;
  --mari-home-violet: #5b6bc4;
  --mari-selected-tint: var(--primary);
  --mari-status-online: #2f9f74;
  --mari-focus-ring-color: var(--p-rose);

  --mari-font-ui: var(--p-pixel);
  --mari-font-heading: var(--p-pixel);
  --mari-font-chat: var(--p-pixel);
  --mari-chat-font-size: 17px;
  --mari-text-outline: 0;
  --mari-dialogue-color: #a82c5c;
  --mari-msg-head-rule: none;
  --mari-composer-placeholder: "> type a message...";
  --mari-user-avatar-placeholder: linear-gradient(#c3c9f1, #c3c9f1);
  --mari-scrim: rgba(74, 35, 64, 0.35);
  --mari-art-saturation-1: 45%;
  --mari-art-lightness-1: 82%;
  --mari-art-saturation-2: 45%;
  --mari-art-lightness-2: 74%;

  /* backdrop: the city, washed toward paper so it never fights the windows */
  --p-city: url("theme:city-day.webp");
  --p-city-land: url("theme:city-day.webp");
  --p-wash: linear-gradient(rgba(251, 227, 239, 0.25), rgba(251, 227, 239, 0.25));
  --mari-app-backdrop-rendering: pixelated;
  --mari-app-backdrop-layers: var(--p-wash), var(--p-city) bottom center / cover no-repeat;
  --mari-home-wash: transparent;
  --mari-home-art: none;
  --mari-page-veil: rgba(251, 227, 239, 0.94);

  /* top bar: a calm dithered taskbar, square plates */
  --mari-top-bar-bg: url("theme:topbar-cx.png") 0 100% / 512px 44px repeat-x, #f4c6d7;
  --mari-top-bar-rendering: pixelated;
  --mari-top-bar-plate: rgba(255, 246, 250, 0.9);
  --mari-top-bar-plate-radius: 0;

  /* home widgets */
  --mari-home-widget-radius: 0;
  --mari-home-widget-border: var(--p-ink);
  --mari-home-widget-border-width: 2px;
  --mari-home-widget-bg: var(--p-paper);
  --mari-home-widget-font: var(--p-pixel);
  --mari-home-widget-title-font: var(--p-pixel);
  --mari-home-widget-title-size: 22px;
  --mari-home-widget-title-color: var(--p-ink);
  --mari-home-widget-eyebrow-size: 15px;
  --mari-home-widget-eyebrow-color: var(--p-rose-text);
  --mari-home-widget-text-size: 15px;
  --mari-home-widget-muted: var(--p-ink-2);
  --mari-home-widget-action-size: 15px;

  /* picture icons and the pointer */
  --mari-icon-send: url("theme:cx-send.png");
  --mari-icon-stop: url("theme:cx-stop.png");
  --mari-icon-attach: url("theme:cx-attach.png");
  --mari-icon-emoji: url("theme:cx-emoji.png");
  --mari-cursor: url("theme:cur-arrow.png") 0 0, auto;
  --mari-cursor-pointer: url("theme:cur-hand.png") 5 0, pointer;

  /* ── v1.4 tokens ── */
  --mari-chat-wash: none;                 /* my own paper wash sits in the backdrop layers */
  --mari-chat-header-bg: none;
  --mari-message-time: var(--p-ink-2);
  --mari-chrome-accent: var(--p-rose);
  --mari-chrome-muted: var(--p-ink-2);
  --mari-min-ui-text: 13px;
  --mari-toast-font-size: 15px;
  --mari-home-shortcut-size: 15px;
  --mari-home-shortcut-desc-size: 14px;
  --mari-home-widget-glow: transparent;
  --mari-top-bar-plate-active: var(--p-paper);
  --mari-resource-accent: #a82c5c;
  --mari-resource-characters: #a82c5c;
  --mari-resource-personas: #5b6bc4;
  --mari-resource-lorebooks: #2f7f68;
  --mari-resource-presets: #8a4f00;
  --mari-resource-connections: #5b6bc4;
  --mari-resource-agents: #7a4468;
  --mari-resource-settings: #4a2340;
  --mari-resource-backgrounds: #a82c5c;
  --mari-resource-browser: #2f7f68;
  --mari-ctrlk-conversation: #5b6bc4;
  --mari-ctrlk-roleplay: #a82c5c;
  --mari-ctrlk-game: #2f7f68;
  --mari-game-combat-bg: #e05a8a;
  --mari-game-combat-bg-hover: #c23d70;
  --mari-game-combat-border: #4a2340;
  --mari-lore-constant: #c23d70;
  --mari-lore-selective: #5b6bc4;
  --mari-lore-normal: #2f9f74;
  --mari-user-avatar-image: url("theme:av-user.png");
  --p-av-bot: url("theme:av-bot.png");
  /* the "active window": pixel selection handles + a dotted marquee round the newest reply,
     Ctrl+K, dialogs and Recent chats (7 px slice = 5 px outset + my 2 px frame) */
  --mari-focus-frame: url("theme:focus-day.png") 7 / 7px round;
  --mari-focus-frame-outset: 5px;
  /* a few pixel petals drifting in the side gutters, behind the windows */
  --mari-ambient: url("theme:petals.png") 0 0 / 400px 400px repeat;
  --mari-ambient-opacity: 0.5;
  --mari-ambient-placement: behind-cards;
  --mari-ambient-mask: var(--mari-gutter-mask);
  --mari-gutter-clear: 28rem;
  --mari-ambient-animation: p-petals 90s linear infinite;

  /* ── v1.5 tokens: long replies read like a text file ── */
  --mari-message-measure: 34em; /* Petal Pixel runs narrow: 34em is about 68 real characters */
  --mari-chat-line-height: 1.6;
  --mari-paragraph-gap: 0.8em;
  --mari-dialogue-weight: 400;
  --mari-message-actions: var(--p-ink-2);
  --mari-swipe-counter: var(--p-ink-2);
  --mari-scrim: rgba(74, 35, 64, 0.34);
  --mari-chat-row-art-opacity: 0;
  --mari-card-art-placeholder: var(--p-av-bot) center / 46% no-repeat, var(--p-dots) 0 0 / 10px 10px, var(--p-shell-2);

  --mari-gauge-ok: #2f9f74;
  --mari-gauge-warn: #c98a1c;
  --mari-gauge-danger: #c2334f;
  --mari-stage-empty-bg: transparent;
}

/* ── NIGHT: plum desk, CRT windows, glowing pink title bars. Its own look, not an inversion ── */
:root[data-theme="dark"] {
  --p-ink: #f6e7f0;
  --p-ink-2: #d9bfd6;
  --p-paper: #33264b;
  --p-paper-2: #2a1f3f;
  --p-shell: #ff8fba;
  --p-shell-2: #4a3768;
  --p-rose: #ff6fa5;
  --p-rose-text: #ff9ec4;
  --p-peri: #a9b4ee;
  --p-hi: #4c3b6e;
  --p-lo: #1f1530;
  --p-drop: rgba(10, 4, 18, 0.55);
  --p-desk: #2b1e3d;
  --p-title-ink: #2b1e3d;
  --p-edge: #ff8fba;
  --p-btns: url("theme:winbtns-night.png");
  --p-heart: url("theme:heart-n.png");
  --p-dots: url("theme:dots-night.png");

  --background: #2b1e3d;
  --primary: #ff6fa5;
  --primary-foreground: #2b1e3d;
  --border: #6e5a96;
  --input: #6e5a96;
  --sidebar: #2b1e3d;
  --sidebar-border: #ff8fba;
  --destructive: #ff6b81;
  --destructive-foreground: #2b1e3d;
  --ov-line: #5b4a82;
  --ov-dim: #bba2c4;
  --ov-hover: rgba(255, 143, 186, 0.12);
  --ov-active-bg: rgba(255, 143, 186, 0.2);
  --ov-mode-conversation: #a9b4ee;
  --ov-mode-roleplay: #ff9ec4;
  --ov-mode-game: #8fdcc0;
  --mari-mode-conversation: #a9b4ee;
  --mari-mode-roleplay: #ff9ec4;
  --mari-mode-game: #8fdcc0;
  --mari-home-pink: #ff9ec4;
  --mari-home-violet: #a9b4ee;
  --mari-status-online: #8fdcc0;
  --mari-dialogue-color: #ffb3d1;
  --mari-user-avatar-placeholder: linear-gradient(#5b4a82, #5b4a82);
  --mari-scrim: rgba(10, 4, 18, 0.55);
  --mari-art-saturation-1: 32%;
  --mari-art-saturation-2: 32%;
  --mari-art-lightness-1: 36%;
  --mari-art-lightness-2: 28%;

  --p-frame: #ff8fba;
  --mari-message-time: var(--p-ink-2);
  --mari-resource-accent: #ff9ec4;
  --mari-resource-characters: #ff9ec4;
  --mari-resource-personas: #a9b4ee;
  --mari-resource-lorebooks: #8fdcc0;
  --mari-resource-presets: #ffd88a;
  --mari-resource-connections: #a9b4ee;
  --mari-resource-agents: #e6b8f0;
  --mari-resource-settings: #f6e7f0;
  --mari-resource-backgrounds: #ff9ec4;
  --mari-resource-browser: #8fdcc0;
  --mari-ctrlk-conversation: #a9b4ee;
  --mari-ctrlk-roleplay: #ff9ec4;
  --mari-ctrlk-game: #8fdcc0;
  --mari-game-combat-bg: #ff6fa5;
  --mari-game-combat-bg-hover: #ff8fba;
  --mari-game-combat-border: #ffd6e7;
  --mari-lore-constant: #ff8fba;
  --mari-lore-selective: #a9b4ee;
  --mari-lore-normal: #8fdcc0;
  --p-av-bot: url("theme:av-bot-n.png");
  --mari-user-avatar-image: url("theme:av-user-n.png");
  --mari-focus-frame: url("theme:focus-night.png") 7 / 7px / 5px round;
  --mari-ambient-opacity: 0.45;
  --p-city: url("theme:city-night.webp");
  --p-city-land: url("theme:city-night.webp");
  --p-wash: linear-gradient(rgba(43, 30, 61, 0.12), rgba(43, 30, 61, 0.12));
  --mari-page-veil: rgba(43, 30, 61, 0.95);
  --mari-top-bar-bg: url("theme:topbar-night.png") 0 0 / 256px 44px repeat-x, #2b1e3d;
  --mari-top-bar-plate: rgba(51, 38, 75, 0.92);
  --mari-home-widget-border: #ff8fba;
  --mari-home-widget-bg: #33264b;
  --mari-home-widget-title-color: #f6e7f0;
  --mari-home-widget-eyebrow-color: #ff9ec4;
  --mari-home-widget-muted: #d9bfd6;
  --mari-stage-empty-bg: transparent;
}

/* a chat tagged "Night Shift" always gets the night city, even by day */
:root[data-chat-tags~="night-shift"] { --p-city: url("theme:city-night.webp"); --p-city-land: url("theme:city-night.webp"); }

/* ══════════ base type ══════════ */
.mari-app { font-family: var(--p-pixel); color: var(--p-ink); }
h1, h2, h3, [data-component="OverhaulEditorHead"] h1 {
  font-family: var(--p-pixel) !important;
  font-weight: 700;
  letter-spacing: 0.01em;
}
:is(button, input, select, textarea, [role="tab"], [role="option"], [role="menuitem"]) { border-radius: 0 !important; }
/* one corner language: square, everywhere (pixel windows have no round corners) */
body *:not(svg, svg *), body *::before, body *::after { border-radius: 0 !important; }
::selection { background: #ffb3d1; color: #4a2340; }

/* ══════════ the window recipe ══════════
   2 px ink frame, a flat title bar (28 px) with _ [] X at the right, a 2 px rule under it, and a hard
   4 px pixel shadow. All CSS layers, so it is crisp at any zoom. Title text comes from --p-title. */
.p-win,
div:has(> [data-roleplay-vn-navigation]),
[role="dialog"]:not(.mari-modal):not(.mari-window):not(.inset-0):not(:has(> [data-mari-part="window-title"])) {
  --p-tb: var(--p-shell);
  /* longhands only: the `border` shorthand would reset the app's focus-frame border-image */
  border-width: 2px !important;
  border-top-width: calc(var(--p-t) + 2px) !important;
  border-style: solid !important;
  border-color: transparent var(--p-frame, var(--p-ink)) var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background-color: var(--p-paper) !important;
  background-image:
    var(--p-btns),
    linear-gradient(var(--p-frame, var(--p-ink)), var(--p-frame, var(--p-ink))),
    linear-gradient(var(--p-frame, var(--p-ink)), var(--p-frame, var(--p-ink))),
    linear-gradient(var(--p-tb), var(--p-tb)) !important;
  background-size: 43px 11px, 100% 2px, 100% 2px, 100% var(--p-t) !important;
  background-position: right 7px top calc(var(--p-t) / 2 - 4.5px), 0 0, 0 var(--p-t), 0 0 !important;
  background-repeat: no-repeat !important;
  background-origin: border-box !important;
  background-clip: border-box !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
  color: var(--p-ink);
  image-rendering: pixelated;
}
:root[data-theme="dark"] :is(
  .p-win, [data-mari-part="home-widget"], .mari-rp-bubble,
  [data-mari-part="message"][data-game-narration], .mari-chat-input-box, [data-component="GlobalOmnibar.Panel"],
  .mari-window.mari-window, .mari-modal-panel.mari-modal-panel, [role="dialog"]:not(.mari-modal):not(.mari-window)
) {
  --p-frame: #ff8fba;
  box-shadow: 4px 4px 0 var(--p-drop), 0 0 0 1px rgba(255, 143, 186, 0.25), 0 0 18px rgba(255, 111, 165, 0.18) !important;
}

@keyframes p-petals { to { background-position: 100px 800px; } }

/* ══════════ windows with a real title slot (--mari-window-title: on) ══════════
   Messages, Home widgets and the message box get the app's own title row; I only paint it. */
.mari-rp-bubble,
[data-mari-part="home-widget"],
.mari-chat-input-box,
[data-mari-part="message"][data-game-narration],
[data-component="GlobalOmnibar.Panel"],
.mari-window.mari-window,
.mari-modal-panel.mari-modal-panel {
  border-width: 2px !important;
  border-style: solid !important;
  border-color: var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
  color: var(--p-ink);
}
:root[data-theme="dark"] :is(.mari-rp-bubble, [data-mari-part="home-widget"], .mari-chat-input-box) {
  box-shadow: 4px 4px 0 var(--p-drop), 0 0 18px rgba(255, 111, 165, 0.16) !important;
}
[data-mari-part="window-title"] {
  --p-tb: var(--p-shell);
  position: relative;
  z-index: 3;
  box-sizing: border-box;
  height: var(--p-t);
  min-height: var(--p-t);
  padding: 0 8px 0 30px;
  gap: 8px;
  background: var(--p-heart) 9px center / 14px 12px no-repeat, var(--p-tb);
  border-bottom: 2px solid var(--p-frame, var(--p-ink));
  font: 400 20px/1 var(--p-term);
  letter-spacing: 0.04em;
  text-transform: lowercase;
  color: var(--p-title-ink);
  image-rendering: pixelated;
  pointer-events: none;
}
[data-mari-part="window-title-text"] { line-height: calc(var(--p-t) - 2px); position: relative; top: -1px; }
[data-mari-part="window-buttons"] {
  flex: 0 0 43px;
  margin-left: auto;
  height: 11px;
  background: var(--p-btns) 0 0 / 43px 11px no-repeat;
  image-rendering: pixelated;
}
:root[data-mari-contrast="more"] [data-mari-part="window-title"] { --p-tb: var(--p-paper); }

/* roleplay: the speaker's title bar stays pinned while you read a long reply. It is sticky inside
   the chat list, so it can never rise over the top bar. */
.mari-rp-bubble > div { padding: 0 18px 14px !important; position: relative; }
.mari-rp-bubble [data-mari-part="window-title"] {
  position: sticky;
  /* the chat list keeps top padding for its floating buttons; sticky counts from inside it */
  top: calc(0px - var(--mari-roleplay-content-padding-top, 52px));
  margin: 0 -18px 12px;
  padding-right: 8px;
  box-shadow: 0 2px 0 var(--p-paper), 0 4px 0 var(--p-drop);
}
:root[data-theme="dark"] .mari-rp-bubble [data-mari-part="window-title"] { border-bottom-color: #4a2340; }
.mari-rp-bubble--user [data-mari-part="window-title"] { --p-tb: var(--p-peri); }
/* time and message tools ride in the title bar, left of _ [] X */
/* v1.5 pinned speaker: the app's name line is a 0-high sticky strip at the title bar's lower edge,
   its time and tools lifted into the bar. It pins with the title, and the guard reads text below it */
:root {
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bg: transparent;
  --mari-pinned-speaker-bleed: 0px;
}
.mari-rp-bubble .ov-rpmsg__head {
  position: sticky !important;
  top: calc(var(--p-t) - var(--mari-roleplay-content-padding-top, 52px)) !important;
  height: 0;
  min-height: 0 !important;
  margin: -12px -18px 12px !important;
  padding: 0 62px 0 0 !important;
  gap: 6px;
  z-index: 4;
  display: flex !important;
  justify-content: flex-end;
  align-items: flex-start !important;
  background: transparent !important;
  overflow: visible;
  --mari-message-time: var(--p-title-ink);
}
.mari-rp-bubble .ov-rpmsg__head > * { position: relative; top: calc(2px - var(--p-t)); height: calc(var(--p-t) - 2px); display: inline-flex; align-items: center; }
.mari-rp-bubble .ov-rpmsg__head > .ov-rpmsg__grow { flex: 1 1 auto; order: -1; }
.mari-rp-bubble [data-mari-part="window-title-text"] { flex: 0 1 auto; max-width: calc(100% - 230px); }
.mari-rp-bubble .ov-rpmsg__head [data-mari-part="time"] { font: 18px/1 var(--p-term) !important; letter-spacing: 0.05em; opacity: 0.8; }
.mari-rp-bubble .ov-rpmsg__head .ov-rpf__btn { width: 24px; height: 24px; min-height: 0; color: var(--p-title-ink) !important; }

/* message box: the title row sits on top of the box as one window */
[data-mari-part="composer"] > [data-mari-part="window-title"] {
  border: 2px solid var(--p-frame, var(--p-ink));
  height: calc(var(--p-t) + 2px);
  box-shadow: 4px 4px 0 var(--p-drop);
}
[data-mari-part="composer"] > [data-mari-part="window-title"] + .mari-chat-input-box { border-top: 0 !important; }
[data-window="composer"] [data-mari-part="window-title-text"]::after { content: ".txt"; }

/* Home widgets */
[data-mari-part="home-widget"] { position: relative; overflow: clip !important; padding-top: 0 !important; }
[data-mari-part="home-widget"] > [data-mari-part="window-title"] {
  margin: 0 calc(-1 * clamp(0.8rem, 0.9vw, 1.1rem)) 10px;
}
[data-mari-part="home-widget-glow"] { display: none; }
[data-home-widget-id="professor"] [data-mari-part="home-widget"] { padding-top: calc(var(--p-t) + 8px) !important; }
[data-home-widget-id="professor"] [data-home-professor-content] { position: static !important; }
[data-home-widget-id="professor"] [data-mari-part="window-title"] { position: absolute; top: 0; left: 0; right: 0; --p-tb: var(--p-peri); }
:root[data-theme="dark"] [data-home-widget-id="professor"] [data-mari-part="window-title"] { --p-tb: var(--p-peri); }
[data-home-widget-id="community"] [data-mari-part="window-title"] { --p-tb: var(--p-mint); }
:root[data-theme="dark"] [data-home-widget-id="community"] [data-mari-part="window-title"] { --p-tb: #8fdcc0; }

/* default avatars when nobody picked a picture: the bunny-hood visitor and the bunny CRT */
[data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"][data-role="assistant"],
[data-mari-part="avatar-placeholder"][data-role="assistant"] {
  background: var(--p-av-bot) center / cover no-repeat !important;
  image-rendering: pixelated;
}
[data-mari-part="avatar-placeholder"][data-role="assistant"] > svg { visibility: hidden; }
[data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"][data-role="user"] {
  background: var(--mari-user-avatar-image) center / cover no-repeat !important;
}

/* ══════════ top bar ══════════ */
[data-component="TopBar"] {
  font-family: var(--p-term);
  font-size: 18px;
  letter-spacing: 0.03em;
  --ov-text: #4a2340;
  --ov-muted: #6b3a5c;
  --ov-dim: #6b3a5c;
  color: #4a2340;
}
:root[data-theme="dark"] [data-component="TopBar"] { --ov-text: #f6e7f0; --ov-muted: #e6cde0; --ov-dim: #e6cde0; color: #f6e7f0; }
[data-component="TopBar"] .ov-tab.is-on,
:root[data-mari-top-bar-art] [data-component="TopBar"] :is([aria-pressed="true"], .is-active, .is-on) {
  background-color: var(--p-paper) !important;
  box-shadow: inset 0 0 0 2px var(--p-ink), 2px 2px 0 var(--p-drop) !important;
}
:root[data-theme="dark"] [data-component="TopBar"] .ov-tab.is-on { box-shadow: inset 0 0 0 2px #ff8fba, 2px 2px 0 var(--p-drop) !important; }

/* ══════════ sidebars: dotted desk blotter, square bevel controls ══════════ */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"] {
  background-color: var(--p-desk) !important;
  background-image: var(--p-dots) !important;
  background-size: 10px 10px !important;
  image-rendering: pixelated;
  border-color: var(--p-ink) !important;
}
:root[data-theme="dark"] :is([data-component="ChatSidebar"], [data-component="RightPanelDesktop"]) { border-color: #ff8fba !important; }
[data-component="ChatSidebar"] :is(input, select, [role="tablist"], [role="tab"], button),
[data-component="RightPanelDesktop"] :is(input, select) {
  border-radius: 0 !important;
}
/* raised pixel controls */
.mari-chrome-segmented {
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  border: 2px solid var(--p-ink) !important;
  box-shadow: 3px 3px 0 var(--p-drop) !important;
  padding: 2px !important;
  gap: 2px;
}
.mari-chrome-segmented__button {
  border-radius: 0 !important;
  font-size: 14px !important;
  padding-inline: 4px !important;
  gap: 3px !important;
  color: var(--p-ink-2) !important;
}
.mari-chrome-segmented__button--selected {
  background: var(--p-shell) !important;
  color: #4a2340 !important;
  box-shadow: inset -2px -2px 0 rgba(74, 35, 64, 0.25), inset 2px 2px 0 rgba(255, 255, 255, 0.7) !important;
}
.mari-chrome-field,
.mari-chrome-control,
.ov-icon-btn,
[data-component="RightPanelDesktop"] input {
  border-radius: 0 !important;
  background-color: var(--p-paper) !important;
  border: 2px solid var(--p-ink) !important;
  color: var(--p-ink) !important;
  font-size: 15px !important;
}
.mari-chrome-field { box-shadow: inset 2px 2px 0 var(--p-lo) !important; }
.mari-chrome-control, .ov-icon-btn { box-shadow: inset -2px -2px 0 var(--p-lo), inset 2px 2px 0 var(--p-hi) !important; }
.ov-icon-btn { border-width: 0 !important; background: transparent !important; box-shadow: none !important; }
.ov-icon-btn:hover { background: var(--p-paper) !important; box-shadow: inset 0 0 0 2px var(--p-ink) !important; }
.mari-chrome-field::placeholder { color: var(--p-ink-2) !important; opacity: 1; }
.ov-new-pill {
  border-radius: 0 !important;
  background: var(--p-rose) !important;
  color: #fff6fa !important;
  border: 2px solid #4a2340 !important;
  box-shadow: inset -2px -2px 0 rgba(74, 35, 64, 0.35), inset 2px 2px 0 rgba(255, 255, 255, 0.45), 2px 2px 0 var(--p-drop) !important;
  font-family: var(--p-pixel);
}
:root[data-theme="dark"] .ov-new-pill { color: #2b1e3d !important; }
:root[data-theme="dark"] :is(.mari-chrome-segmented, .mari-chrome-field, .mari-chrome-control, [data-component="RightPanelDesktop"] input) { border-color: #ff8fba !important; }
.mari-sidebar-header { flex-wrap: nowrap !important; }
.mari-sidebar-header .ov-new-pill { font-size: 14px !important; padding: 2px 8px !important; }
.mari-sidebar-header > div > div:first-child { border-radius: 0 !important; background: var(--p-shell) !important; border: 2px solid var(--p-ink); color: #4a2340 !important; box-shadow: none !important; }
.mari-sidebar-header h2 { font-family: var(--p-display) !important; font-size: 13px !important; letter-spacing: 0.02em; overflow: visible; color: var(--p-ink) !important; }
.mari-sidebar-header > .absolute { background: var(--p-ink) !important; height: 2px; opacity: 1; }
[data-chat-row] {
  border-radius: 0 !important;
  font-size: 16px !important;
  color: var(--p-ink) !important;
}
[data-chat-row] *, :has(> [data-chat-row]), .ovm-swiperow { border-radius: 0 !important; }
[data-chat-row]:hover { background-color: var(--p-paper-2) !important; }
[data-chat-row][data-selected="true"] {
  background: var(--p-paper) !important;
  border: 2px solid var(--p-ink) !important;
  box-shadow: inset 4px 0 0 var(--p-rose), 3px 3px 0 var(--p-drop) !important;
  color: var(--p-ink) !important;
}
:root[data-theme="dark"] [data-chat-row][data-selected="true"] { border-color: #ff8fba !important; }
[data-chat-row] img, [data-chat-row] [class*="rounded-full"] { border-radius: 0 !important; image-rendering: pixelated; }

/* app buttons everywhere: raised pixel bevel; primary = rose */
.ov-btn {
  border-radius: 0 !important;
  border: 2px solid var(--p-ink) !important;
  background: var(--p-paper) !important;
  color: var(--p-ink) !important;
  box-shadow: inset -2px -2px 0 var(--p-lo), inset 2px 2px 0 var(--p-hi), 2px 2px 0 var(--p-drop) !important;
}
.ov-btn:hover { background: var(--p-shell-2) !important; }
.ov-btn:active { box-shadow: inset 2px 2px 0 var(--p-lo) !important; }
:is(.ov-btn--primary, .ov-btn--accent) { background: var(--p-rose) !important; color: #fff6fa !important; box-shadow: inset -2px -2px 0 rgba(74, 35, 64, 0.35), inset 2px 2px 0 rgba(255, 255, 255, 0.45), 2px 2px 0 var(--p-drop) !important; }
:root[data-theme="dark"] :is(.ov-btn--primary, .ov-btn--accent) { color: #2b1e3d !important; }
:root[data-theme="dark"] .ov-btn { border-color: #ff8fba !important; }

/* ══════════ chat column ══════════ */
.mari-messages-scroll { scrollbar-color: var(--p-rose) transparent; }
.mari-messages-scroll > div:not(.sticky) { max-width: 900px; margin-inline: auto; }
.mari-messages-scroll { scroll-padding-bottom: 48px; }
.mari-messages-scroll > div:last-child { padding-bottom: 40px; }

/* roleplay: the bubble is the window, its title bar carries the speaker */
.mari-roleplay-message-row { gap: 14px !important; margin-bottom: 22px !important; }
.mari-rp-bubble {
  position: relative;
  overflow: clip !important; /* clip, not hidden: the sticky title bar needs the chat list as its scroller */
  min-width: 260px;
  --tw-ring-shadow: 0 0 #0000 !important;
}
.mari-rp-bubble--user { --p-tb: var(--p-peri); }
/* the touch layout repeats the name above the bubble; the title bar already says it */
.mari-roleplay-message-body > [data-mari-part="header"] { display: none !important; }
.mari-roleplay-message-row > .mari-roleplay-message-body { flex: 1 1 auto; }
.mari-roleplay-message-row .mari-rp-bubble { width: 100%; }

.marinara-chat-toolbar-button {
  border-radius: 0 !important;
  border: 2px solid var(--p-ink) !important;
  background: var(--p-paper) !important;
  box-shadow: 2px 2px 0 var(--p-drop) !important;
  color: var(--p-ink) !important;
}
.marinara-chat-toolbar-button * { border-radius: 0 !important; }

.mari-rp-bubble .mari-message-name {
  position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}
.ov-rpmsg__head { min-height: 0; align-items: center; }
.ov-rpmsg__head > span:nth-child(2) {
  font: 18px/1 var(--p-term) !important;
  letter-spacing: 0.05em;
  color: var(--p-title-ink) !important;
  opacity: 0.75;
}
.mari-message-content {
  font-family: var(--p-pixel) !important;
  font-size: 17px !important;
  color: var(--p-ink) !important;
  -webkit-text-stroke: 0 !important;
}
.mari-message-content :is(strong, b) { color: var(--p-ink) !important; font-weight: 700; }
/* dialogue: the app colours quoted bold; a whole paragraph of bold pixel type is a wall, so dialogue is
   colour only, at reading weight */
.mari-message-content :is(strong, b)[style*="dialogue"],
.mari-message-content q { color: var(--mari-dialogue-color) !important; font-weight: var(--mari-dialogue-weight) !important; }
.mari-message-content :is(em, i) { color: var(--p-ink-2); }
/* scene break: a dotted pixel rule with a heart, not a hairline */
.mari-message-content hr {
  border: 0 !important;
  height: 12px;
  margin: 10px 0 !important;
  background:
    var(--p-heart) center / 14px 12px no-repeat,
    linear-gradient(var(--p-paper), var(--p-paper)) center / 34px 12px no-repeat,
    repeating-linear-gradient(90deg, var(--p-lo) 0 4px, transparent 4px 8px) center / 100% 2px no-repeat;
  image-rendering: pixelated;
}
.mari-message-content :is(ol, ul) { padding-left: 1.6em; }
.mari-message-content li { margin: 2px 0; }
.mari-message-content li::marker { color: var(--p-rose-text); font-family: var(--p-term); font-size: 1.15em; }
.mari-message-content ul > li::marker { content: "\2665  "; font-size: 0.9em; }
.mari-message-content blockquote {
  border-left: 4px solid var(--p-rose);
  background: var(--p-paper-2);
  margin: 8px 0;
  padding: 2px 14px;
}
/* code blocks: a tiny terminal window */
.mari-message-content pre {
  background: #2b1e3d linear-gradient(#ff8fba, #ff8fba) 0 0 / 100% 18px no-repeat !important;
  color: #ffd6e7 !important;
  border: 2px solid #4a2340 !important;
  border-radius: 0 !important;
  box-shadow: 3px 3px 0 var(--p-drop);
  padding: 26px 14px 10px !important;
  font: 19px/1.25 var(--p-term) !important;
  position: relative;
  white-space: pre-wrap;
}
.mari-message-content pre::before {
  content: "> terminal";
  position: absolute; left: 8px; top: 0; font: 17px/18px var(--p-term); color: #2b1e3d;
}
.mari-message-content pre code { background: none !important; border: 0 !important; color: inherit !important; font: inherit !important; padding: 0 !important; }
.mari-message-content :not(pre) > code {
  font: 18px var(--p-term) !important;
  background: var(--p-paper-2) !important;
  border: 1px solid var(--border) !important;
  border-radius: 0 !important;
  padding: 0 5px !important;
  color: var(--p-rose-text) !important;
}

/* avatars: square pixel tiles with a bevel */
[data-mari-part="avatar"] > div,
[data-mari-part="avatar"] button,
[data-mari-part="avatar"] img {
  border-radius: 0 !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  box-shadow: none !important;
  image-rendering: pixelated;
}
[data-mari-part="avatar"] > div:first-child {
  border: 2px solid var(--p-ink);
  box-shadow: inset -3px -3px 0 rgba(74, 35, 64, 0.18), 3px 3px 0 var(--p-drop) !important;
  background-color: var(--p-shell) !important;
  background-image: none;
  color: #4a2340 !important;
}
:root[data-theme="dark"] [data-mari-part="avatar"] > div:first-child { border-color: #ff8fba; }
[data-mari-part="avatar"] > .rpg-avatar-glow { display: block; line-height: 0; }
[data-mari-part="avatar"] > .rpg-avatar-glow > button { display: block; }
.mari-roleplay-message-row { --roleplay-avatar-scale: 1.4 !important; }
.mari-accent-animated, .rpg-avatar-glow { filter: none !important; animation: none; }

/* message tools: square pixel buttons */
.ov-rpf__btn, .ov-rpf__swipes button, .ov-rpf__count {
  border-radius: 0 !important;
  color: var(--p-ink-2) !important;
}
.ov-rpf__btn:hover, .ov-rpf__swipes button:hover {
  background: var(--p-paper-2) !important;
  box-shadow: inset 0 0 0 2px var(--p-ink) !important;
  color: var(--p-ink) !important;
}

/* reasoning: a collapsed "thinking..." strip */
[data-mari-part="reasoning"] {
  font: 18px/1.2 var(--p-term) !important;
  letter-spacing: 0.05em;
  color: var(--p-ink) !important;
  background: var(--p-paper-2) !important;
  border: 2px dashed var(--p-ink-2) !important;
  border-radius: 0 !important;
}
[data-mari-part="reasoning-text"] { font: 18px/1.3 var(--p-term) !important; color: var(--p-ink-2) !important; }

/* ── conversation: the transcript is one messenger window; its sticky header is the title bar ──
   (the message box stays exactly where the app puts it: only the transcript gets the frame) */
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll {
  margin: 52px 22px 10px;
  padding-bottom: 12px !important;
  border: 2px solid var(--p-frame, var(--p-ink));
  background: var(--p-paper);
  box-shadow: 4px 4px 0 var(--p-drop);
}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky {
  max-width: none;
  margin: 0 0 8px;
  min-height: var(--p-t);
  padding: 3px 60px 3px 8px !important;
  background: var(--p-btns) right 7px center / 43px 11px no-repeat, var(--p-shell);
  border-bottom: 2px solid var(--p-frame, var(--p-ink));
  image-rendering: pixelated;
}
:root[data-theme="dark"] .mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll { --p-frame: #ff8fba; box-shadow: 4px 4px 0 var(--p-drop), 0 0 18px rgba(255, 111, 165, 0.18); }
/* the participant button reads as the window's title: heart, name in Petal Term, status beside it */
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button {
  border: 0 !important; background: transparent !important; box-shadow: none !important; padding: 0 6px 0 2px !important; min-height: 0;
}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button > div.relative > div:first-child {
  background: var(--p-heart) center / 14px 12px no-repeat !important; color: transparent !important; image-rendering: pixelated;
}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button > div.flex-col {
  flex-direction: row !important; align-items: baseline !important; gap: 10px;
}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button > div.flex-col > span {
  font: 400 20px/24px var(--p-term) !important; letter-spacing: 0.04em; text-transform: lowercase; color: var(--p-title-ink) !important; width: auto !important; overflow: visible;
}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button > div.flex-col > span + span { font-size: 17px !important; opacity: 0.75; }
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > div:not(.sticky) { max-width: 960px; margin-inline: 10px; }
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message:hover { background: var(--p-paper-2) !important; }
.mari-chat-area[data-chat-mode="conversation"] .mari-message-name { font-size: 17px !important; font-weight: 700; color: var(--p-ink) !important; }
.mari-chat-area[data-chat-mode="conversation"] [data-message-role="user"] .mari-message-name { color: #5b6bc4 !important; }
:root[data-theme="dark"] .mari-chat-area[data-chat-mode="conversation"] [data-message-role="user"] .mari-message-name { color: #a9b4ee !important; }
.mari-chat-area[data-chat-mode="conversation"] .mari-message-timestamp { font: 16px var(--p-term) !important; color: var(--p-ink-2) !important; letter-spacing: 0.04em; }
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="avatar"] button { border: 2px solid var(--p-ink); background: var(--p-shell) !important; }
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="avatar"] button > div { color: #4a2340 !important; font-family: var(--p-display); }
:root[data-theme="dark"] .mari-chat-area[data-chat-mode="conversation"] [data-mari-part="avatar"] button { border-color: #ff8fba !important; }

/* ── game narration ── */
[data-mari-part="message"][data-game-narration] { position: relative; overflow: clip; }
[data-mari-part="message"][data-game-narration]:not([data-character-name]) > [data-mari-part="window-title"] [data-mari-part="window-title-text"]::after { content: ".txt"; }

/* ══════════ composer ══════════ */

:is(.mari-chat-input-textarea, [data-mari-part="composer"] textarea) {
  font: 20px/1.3 var(--p-term) !important;
  letter-spacing: 0.02em;
  color: var(--p-ink) !important;
}
.mari-chat-input-textarea::placeholder { color: var(--p-ink-2) !important; opacity: 1; }
[data-mari-part="composer"] button { border-radius: 0 !important; }
[data-mari-part="composer"] button:hover { background: var(--p-paper-2) !important; box-shadow: inset 0 0 0 2px var(--p-ink) !important; }

/* ══════════ Home ══════════ */

/* the app mark in the chats header becomes the little bunny CRT */
.mari-sidebar-header > div > div:first-child {
  background: url("theme:emblem.png") center / 28px 28px no-repeat !important;
  border: 0 !important;
  width: 28px !important; height: 28px !important;
}
.mari-sidebar-header > div > div:first-child > svg { visibility: hidden; }
/* composer picture icons: the art is wider than tall, give it room */
[data-mari-part="composer"] svg:is(.lucide-send, .lucide-send-horizontal, .lucide-paperclip, .lucide-smile, .lucide-circle-stop, .lucide-square) { width: 24px; height: 24px; }
/* Home greeting sits on a paper label so it reads over any part of the city */
[data-mari-part="home"] h1 {
  display: inline-block;
  background: var(--p-paper);
  border: 2px solid var(--p-ink);
  box-shadow: 4px 4px 0 var(--p-drop);
  padding: 2px 14px 4px;
  color: var(--p-ink) !important;
}
:root[data-theme="dark"] [data-mari-part="home"] h1 { border-color: #ff8fba; }
/* the one sticker in the theme: a bunny peeking over the greeting label (a sleepy moon at night) */
[data-mari-part="home"] h1 { position: relative; }
[data-mari-part="home"] h1::after {
  content: ""; position: absolute; right: -46px; top: -30px; width: 44px; height: 44px;
  background: url("theme:st-bunny.png") center / contain no-repeat; rotate: 10deg; pointer-events: none;
}
:root[data-theme="dark"] [data-mari-part="home"] h1::after { background-image: url("theme:st-moon.png"); }
[data-mari-part="home-widget-eyebrow"] { font-family: var(--p-term) !important; letter-spacing: 0.06em; }

/* ══════════ menus, listboxes, toasts, Ctrl+K ══════════ */
[role="menu"], [role="listbox"], [data-radix-popper-content-wrapper] > [role="tooltip"] {
  border: 2px solid var(--p-ink) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
  color: var(--p-ink);
}
:root[data-theme="dark"] :is([role="menu"], [role="listbox"]) { border-color: #ff8fba !important; }
:is([role="menuitem"], [role="option"]):is(:hover, [data-highlighted], [aria-selected="true"]) {
  background: var(--p-shell) !important;
  color: #4a2340 !important;
}
[data-component="GlobalOmnibar.Panel"] input { font: 20px var(--p-term) !important; }
/* drawer sections inside a window: flat paper panels with a dashed rule, not windows-in-windows */
.mari-drawer {
  border-radius: 0 !important;
  border: 0 !important;
  border-bottom: 2px dashed var(--ov-line) !important;
  background: transparent !important;
  box-shadow: none !important;
}
[data-sonner-toast] {
  border: 2px solid var(--p-ink) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  background-image: linear-gradient(var(--p-shell), var(--p-shell)) !important;
  background-size: 8px 100% !important;
  background-repeat: no-repeat !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  color: var(--p-ink) !important;
  font-family: var(--p-pixel) !important;
  font-size: 15px !important;
  padding-left: 20px !important;
}
:root[data-theme="dark"] [data-sonner-toast] { border-color: #ff8fba !important; }

/* ══════════ pages: Settings, Library, editors ══════════ */
[role="switch"], [role="switch"] > span, [role="checkbox"] { border-radius: 0 !important; }
[role="switch"] { box-shadow: inset 0 0 0 2px var(--p-ink) !important; }
[role="switch"] > span { box-shadow: 0 0 0 2px var(--p-ink) !important; }
[data-component="OverhaulCardGallery"] :is(img, [class*="rounded"]) { border-radius: 0 !important; }
.ov-card__art {
  border-radius: 0 !important;
  border: 2px solid var(--p-ink) !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  image-rendering: pixelated;
}
:root[data-theme="dark"] .ov-card__art { border-color: #ff8fba !important; }
.ov-card__tokens { border-radius: 0 !important; font-family: var(--p-term) !important; font-size: 16px !important; background: var(--p-paper) !important; color: var(--p-ink) !important; border: 2px solid var(--p-ink); }
:is([data-component="OverhaulLibraryPage"], [data-component="OverhaulCardGallery"], .ov-gallery) :is(input, select) {
  border-radius: 0 !important;
  border: 2px solid var(--p-ink) !important;
  background-color: var(--p-paper) !important;
  box-shadow: inset 2px 2px 0 var(--p-lo) !important;
  color: var(--p-ink) !important;
}
[data-component="OverhaulSettingsPage"] :is(input, select, textarea),
[data-component="OverhaulLibraryPage"] :is(input, select, textarea) {
  border-radius: 0 !important;
  border: 2px solid var(--p-ink) !important;
  background-color: var(--p-paper) !important;
  box-shadow: inset 2px 2px 0 var(--p-lo) !important;
}

/* search fields that are a box with an icon and a bare input: frame the box, not the input */
:is([data-component="OverhaulSettingsPage"], [data-component="OverhaulLibraryPage"], [data-component="OverhaulCardGallery"], .ov-gallery) :is(label, div):has(> svg):has(> input:is([type="text"], [type="search"], :not([type]))) {
  border: 2px solid var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background-color: var(--p-paper) !important;
  box-shadow: inset 2px 2px 0 var(--p-lo) !important;
}
:is([data-component="OverhaulSettingsPage"], [data-component="OverhaulLibraryPage"], [data-component="OverhaulCardGallery"], .ov-gallery) :is(label, div):has(> svg):has(> input:is([type="text"], [type="search"], :not([type]))) > input {
  border: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  outline: none;
}

/* portrait screens get the tall city (same street, recomposed by the art model) */
@media (orientation: portrait) and (max-width: 1100px) {
  :root { --p-city: url("theme:city-day-port.webp"); }
  :root[data-theme="dark"], :root[data-chat-tags~="night-shift"] { --p-city: url("theme:city-night-port.webp"); }
}

/* narrow chat column (phones, or a desktop with both side panes open): the avatar becomes the
   window's app icon in its title bar, so the text keeps a full reading measure */
@container (max-width: 860px) {
  /* phones: the avatar becomes the window's app icon in the title bar, so the text gets the full width.
     The row hugs its window, so the icon lands in the title even where the app centres a narrower body (iPad Mini) */
  .mari-roleplay-message-row { position: relative; gap: 0 !important; }
  .mari-roleplay-message-row > .mari-roleplay-message-body { max-width: 100% !important; width: 100% !important; flex: 1 1 100% !important; }
  .mari-roleplay-message-row > [data-mari-part="avatar"] {
    position: absolute !important;
    z-index: 5;
    top: 4px;
    left: calc(0.5rem + 6px);
    padding: 0 !important;
    pointer-events: auto;
  }
  .mari-roleplay-message-row > [data-mari-part="avatar"] :is(img, button, [data-mari-part="avatar-placeholder"], div) {
    width: 22px !important; height: 22px !important; min-width: 0 !important;
    border-width: 1px !important; box-shadow: none !important;
  }
  .mari-roleplay-message-row > [data-mari-part="avatar"] > div:first-child { border: 1px solid var(--p-title-ink) !important; }
  .mari-rp-bubble [data-mari-part="window-title"] { padding-left: 38px; background-image: none; }
}
@media (max-width: 640px) {
  /* phones: the avatar becomes the window's app icon in the title bar, so the text gets the full width */
  .mari-roleplay-message-row { position: relative; gap: 0 !important; }
  .mari-roleplay-message-row > .mari-roleplay-message-body { max-width: 100% !important; width: 100% !important; flex: 1 1 100% !important; }
  .mari-roleplay-message-row > [data-mari-part="avatar"] {
    position: absolute !important;
    z-index: 5;
    top: 4px;
    left: calc(0.5rem + 6px);
    padding: 0 !important;
    pointer-events: auto;
  }
  .mari-roleplay-message-row > [data-mari-part="avatar"] :is(img, button, [data-mari-part="avatar-placeholder"], div) {
    width: 22px !important; height: 22px !important; min-width: 0 !important;
    border-width: 1px !important; box-shadow: none !important;
  }
  .mari-roleplay-message-row > [data-mari-part="avatar"] > div:first-child { border: 1px solid var(--p-title-ink) !important; }
  .mari-rp-bubble [data-mari-part="window-title"] { padding-left: 38px; background-image: none; }
}

/* ══════════ phones ══════════ */
@media (max-width: 640px) {
  :root { --p-t: 26px; }
  .mari-rp-bubble { min-width: 0; }
  .mari-rp-bubble > div { padding: 0 12px 12px !important; }
  .mari-rp-bubble [data-mari-part="window-title"] { margin: 0 -12px 10px; position: relative; top: auto; }
  /* the touch layout prints name + time above the bubble: lift the time into the title bar */
  .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    display: flex !important;
    position: absolute !important;
    top: 2px;
    right: 68px;
    height: calc(var(--p-t) - 2px);
    align-items: center !important;
    z-index: 4;
    padding: 0 !important;
    --mari-message-time: var(--p-title-ink);
  }
  .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] .mari-message-name { display: none !important; }
  .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] [data-mari-part="time"] { font: 17px/1 var(--p-term) !important; opacity: 0.8; }
  .mari-rp-bubble [data-mari-part="window-title-text"] { max-width: calc(100% - 120px); }
  .mari-message-content { font-size: 16px !important; }
  /* portrait phone, Game: lift the skyline into the stage; the narration window hides the seam */
  :root[data-chat-open-mode="game"] {
    --mari-app-backdrop-layers: var(--p-wash), var(--p-city-land) top center / auto 51% no-repeat;
  }
  .mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll { margin: 10px 10px 8px; }
  .mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll > div:not(.sticky) { margin-inline: 0; }
}

/* ══════════ motion and contrast ══════════ */
@media (prefers-reduced-motion: reduce) {
  .mari-app * { animation-duration: 0.01ms !important; }
}
:root[data-mari-contrast="more"] { --p-drop: transparent; }

/* the game composer lives inside the narration window: no second title bar there */
[data-mari-part="message"][data-game-narration] .mari-chat-input-box,
[data-composer="game"] .mari-chat-input-box {
  border: 2px solid var(--p-ink) !important;
  background-image: none !important;
  box-shadow: inset 2px 2px 0 var(--p-lo) !important;
}
[data-composer="game"] [data-mari-part="window-title"] { display: none !important; }

/* the persona switcher in the message box: no picture yet -> the bunny-hood visitor, not a grey letter */
.mari-chat-input-box button[aria-haspopup="dialog"]:not([aria-label]):not(:has(img)) > div {
  background: var(--mari-user-avatar-image) center / cover no-repeat !important;
  color: transparent !important;
  border: 2px solid var(--p-ink);
  image-rendering: pixelated;
}
.mari-chat-input-box button[aria-haspopup="dialog"]:not([aria-label]) { border-radius: 0 !important; }

/* message action menus and the conversation reaction bar: square paper with a hard pixel shadow */
.ov-rpf-pop {
  border: 2px solid var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
  color: var(--p-ink) !important;
}
.ov-rpf-pop :is(button, [role="menuitem"]) { border-radius: 0 !important; }
.ov-rpf-pop :is(button, [role="menuitem"]):hover { background: var(--p-shell) !important; color: #4a2340 !important; }
.ov-rpf-pop__label { font-family: var(--p-term) !important; font-size: 17px !important; letter-spacing: 0.06em; color: var(--p-rose-text) !important; }

/* conversation: your own avatar is the bunny-hood visitor until you pick a picture */
.mari-chat-area[data-chat-mode="conversation"] [data-message-role="user"] [data-mari-part="avatar"] button:not(:has(img)) > div {
  background: var(--mari-user-avatar-image) center / cover no-repeat;
  color: transparent !important;
  image-rendering: pixelated;
}
.mari-chat-area[data-chat-mode="conversation"] [data-message-role="user"] [data-mari-part="avatar"] button:not(:has(img)) svg { visibility: hidden; }
[data-mari-part="chat-header"] .marinara-chat-toolbar-button { border-radius: 0 !important; }

/* Game: the map-and-party float and the narration tool row become little pixel windows and keys */
[data-mari-part="game-hud"] .mari-game-narration-surface {
  border: 2px solid var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  box-shadow: 4px 4px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
  color: var(--p-ink) !important;
}
[data-mari-part="game-hud"] :is(button, span, [class*="rounded"]) { border-radius: 0 !important; }
[data-mari-part="game-hud"] span { color: var(--p-ink-2) !important; font-size: 14px !important; }
[data-mari-part="game-hud"] button {
  border: 2px solid var(--p-ink) !important;
  background: var(--p-shell-2) !important;
  color: var(--p-ink) !important;
  box-shadow: inset -2px -2px 0 var(--p-lo), inset 2px 2px 0 var(--p-hi) !important;
}
[data-mari-part="game-hud"] button:disabled { opacity: 0.7; }
[data-mari-part="game-tools"] button {
  border: 2px solid var(--p-ink) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  color: var(--p-ink) !important;
  font-family: var(--p-term) !important;
  font-size: 17px !important;
  box-shadow: inset -2px -2px 0 var(--p-lo), inset 2px 2px 0 var(--p-hi), 2px 2px 0 var(--p-drop) !important;
}
[data-mari-part="game-tools"] button:hover { background: var(--p-shell-2) !important; }
:root[data-theme="dark"] :is([data-mari-part="game-tools"] button, [data-mari-part="game-hud"] button) { border-color: #ff8fba !important; }
/* the narration's "Narration" pill duplicates the title bar */
[data-mari-part="message"][data-game-narration] > :is(div:first-child, [data-mari-part="window-title"] + div) > span.rounded-full { display: none; }
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  border-radius: 0 !important;
  border: 0 !important;
  background: transparent !important;
  font-family: var(--p-pixel);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose > div:first-child { font-size: 17px !important; line-height: 1.6 !important; color: var(--p-ink) !important; }

/* Library cards and editor pictures with no art yet: the bunny CRT on a dotted pink tile */
.mari-avatar-placeholder {
  background: var(--p-av-bot) center / min(55%, 128px) no-repeat, var(--p-dots) 0 0 / 10px 10px, var(--p-shell-2) !important;
  image-rendering: pixelated;
}
.mari-avatar-placeholder--persona { background: var(--mari-user-avatar-image) center / min(55%, 128px) no-repeat, var(--p-dots) 0 0 / 10px 10px, var(--p-shell-2) !important; }
.mari-avatar-placeholder > svg:only-child, .mari-avatar-placeholder > div > svg.lucide-user { visibility: hidden; }
/* conversation hover bar */
.ov-cvh {
  border: 2px solid var(--p-frame, var(--p-ink)) !important;
  background: var(--p-paper) !important;
  box-shadow: 3px 3px 0 var(--p-drop) !important;
  backdrop-filter: none !important;
}
.ov-cvh button:hover { background: var(--p-shell) !important; }

/* modal dialogs: the full-screen layer stays a plain scrim; the panel is the window, with the focus frame */
.mari-modal { border: 0 !important; border-image: none !important; background: transparent !important; box-shadow: none !important; }
.mari-modal-backdrop { backdrop-filter: none !important; }
/* windows, dialogs, Ctrl+K and Game narration: the app's own title row (v1.5) is the title bar */
:is(.mari-window, .mari-modal-panel, [data-component="GlobalOmnibar.Panel"], [data-game-narration]) > [data-mari-part="window-title"] {
  display: flex; align-items: center; flex: 0 0 auto;
}
[data-window="omnibar"] [data-mari-part="window-title-text"]::after { content: ".exe"; }
[data-window="narration"] { --p-tb: var(--p-peri); }
[data-mari-part="message"][data-game-narration] > [data-mari-part="window-title"] { margin: -0.75rem -0.75rem 10px; }
.ov-card__art { image-rendering: pixelated; }
/* the chat settings window clips its overflow: let the title text in the border band show */
.mari-window.marinara-chat-popover { overflow: clip !important; overflow-clip-margin: border-box; }
/* quick switches on phones: the switch is the track, not the whole tile */
.ovm-csq__switch[role="switch"] { box-shadow: none !important; }
.ovm-csq__switch[role="switch"] > span:not(.ovm-csq__track) { box-shadow: none !important; }
.ovm-csq__track { box-shadow: inset 0 0 0 2px var(--p-ink) !important; }
.ovm-csq__thumb { box-shadow: 0 0 0 2px var(--p-ink) !important; }

/* ══════════ Visual Novel: the text box is one more little window ══════════ */
div:has(> [data-roleplay-vn-navigation]) { --p-tb: var(--p-shell); }
[data-mari-part="vn-text"] { font-family: var(--p-pixel); }
[data-roleplay-vn-navigation] { border-top: 2px dashed var(--ov-line, var(--p-lo)) !important; padding: 6px 10px !important; }
[data-mari-part="vn-counter"] { font: 18px/1 var(--p-term) !important; letter-spacing: 0.06em; color: var(--p-ink-2); opacity: 1 !important; }
[data-mari-part="vn-nav"] {
  border: 2px solid var(--p-frame, var(--p-ink)) !important;
  border-radius: 0 !important;
  background: var(--p-paper) !important;
  box-shadow: 2px 2px 0 var(--p-drop);
  color: var(--p-ink) !important;
  font: 17px/1 var(--p-term) !important;
  letter-spacing: 0.04em;
  text-transform: lowercase;
  padding: 3px 8px !important;
}
[data-mari-part="vn-nav"]:hover { background: var(--p-shell) !important; color: #4a2340 !important; }
[data-mari-part="vn-nav"]:active { transform: translate(2px, 2px); box-shadow: none; }
:root[data-theme="dark"] [data-mari-part="vn-nav"] { border-color: #ff8fba !important; }
:root { --mari-vn-fade: 1.5rem; }
[data-mari-part="vn-nav"], [data-mari-part="vn-counter"] { white-space: nowrap; }
@media (max-width: 640px) {
  [data-mari-part="vn-nav"] > span { display: none; }
  [data-mari-part="vn-nav"] { padding: 4px 14px !important; }
}

.mari-modal-panel > [data-mari-part="window-title"] + div > h2:first-child { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.mari-modal-panel > [data-mari-part="window-title"] + div { justify-content: flex-end !important; }

/* tablets: the app lays roleplay rows out on a grid; the icon shares the window's cell, in its title bar */
@media (min-width: 641px) and (max-width: 1100px) {
  @container (max-width: 860px) {
    [data-chat-mode="roleplay"] .mari-roleplay-message-row > [data-mari-part="avatar"] {
      grid-column: 3 !important; grid-row: 1 !important;
      position: relative !important; justify-self: start !important; align-self: start !important;
      top: 4px; left: 8px;
    }
  }
}
/* the message tools don't push the time: they sit over it, and the time steps aside while they show */
.mari-rp-bubble .ov-rpmsg__head > .ov-rpf { position: absolute !important; right: 62px; top: calc(2px - var(--p-t)); background: var(--p-tb); z-index: 1; }
.mari-rp-bubble .ov-rpmsg__head > .ov-rpf:not([style*="opacity: 1"]) { pointer-events: auto; }


/* ═══ Weather (theme weather tokens) ═══
   The story's weather in pixels: every drop, flake and star sits on a 3 px grid, petals are the
   theme's own pixel petals at their art size (11 px x 3), and the city greys over in bad weather.
   The night city already has a moon, so the app doesn't draw a second one. */
:root {
  --mari-weather-style: pixel;
  --mari-weather-pixel-size: 3px;
  --mari-weather-tint-strength: 0.4;
  --mari-weather-strength: 1.3;
  --mari-weather-rain-color: #ffaacd;
  --mari-weather-rain-length: 1.4;
  --mari-weather-snow-color: #fff0f7;
  --mari-weather-hail-color: #fff0f7;
  --mari-weather-fog-color: #f3c6dc;
  --mari-weather-petal-image: url("theme:wx-petal-1.png") url("theme:wx-petal-2.png") url("theme:wx-petal-3.png");
  --mari-weather-petal-size: 3;
  --mari-weather-leaf-color: #e58fb4;
  --mari-weather-star-color: #ffd6ea;
  --mari-weather-firefly-color: #ffb3d6;
  --mari-weather-sun-color: #ffe9a8;
  --mari-weather-moon-color: #ffe2f0;
  --mari-weather-lightning-color: #ffd1e6;
}
:root[data-theme="dark"], :root[data-chat-tags~="night-shift"] { --mari-weather-moon: none; }
:root:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="snow"], [data-mari-weather="hail"], [data-mari-weather="fog"], [data-mari-weather="cloudy"]) { --p-city: url("theme:city-overcast-day.webp"); --p-city-land: url("theme:city-overcast-day.webp"); }
:root:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="snow"], [data-mari-weather="hail"], [data-mari-weather="fog"], [data-mari-weather="cloudy"]):is([data-theme="dark"], [data-chat-tags~="night-shift"]) {
  --p-city: url("theme:city-overcast-night.webp");
  --p-city-land: url("theme:city-overcast-night.webp");
}
@media (orientation: portrait) and (max-width: 1100px) {
  :root:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="snow"], [data-mari-weather="hail"], [data-mari-weather="fog"], [data-mari-weather="cloudy"]) { --p-city: url("theme:city-overcast-day-port.webp"); }
  :root:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="snow"], [data-mari-weather="hail"], [data-mari-weather="fog"], [data-mari-weather="cloudy"]):is([data-theme="dark"], [data-chat-tags~="night-shift"]) { --p-city: url("theme:city-overcast-night-port.webp"); }
}
:root[data-mari-weather]:not([data-mari-weather="clear"], [data-mari-weather="cloudy"]) { --mari-ambient: none; }
